bool safeCode(const QString &code,int maximum=80){return QRegularExpression(QStringLiteral("^[A-Za-z0-9_-]{1,%1}$").arg(maximum)).match(code).hasMatch();}
bool safeDepartmentCode(const QString &code){if(code.isEmpty()||code.size()>160)return false;for(const QChar c:code)if(c.unicode()<32)return false;return true;}
void require(bool ok,const char *failure){if(!ok)throw Failure(QString::fromLatin1(failure));}
bool safeUrl(const QUrl &u){return u.isValid()&&u.scheme()==QStringLiteral("https")&&u.host().toLower()==HOST&&u.userName().isEmpty()&&u.password().isEmpty()&&(u.port(-1)==-1||u.port()==443)&&u.fragment().isEmpty();}
