QJsonArray Broker::sessionCookies()const{require(QThread::currentThreadId()==d->owner,"native_broker_owner_thread_required");require(!d->active,"site_request_not_idle");return d->jar.snapshot();}
void Broker::restoreSessionCookies(const QJsonArray &cookies){d->check();require(d->bookingRuntime&&!d->active&&!d->accepted&&d->proc.state()==QProcess::NotRunning&&d->dispatchCount==0,"cookie_restore_requires_fresh_booking_session");QList<QJsonObject> checked;for(const auto &v:cookies){require(v.isObject(),"cookie_attributes_invalid");checked.append(d->jar.validate(v.toObject()));}d->jar.clear();for(const auto &c:checked)d->jar.put(c);d->jar.sync();}
